@end
static void Write37(id x,NSString*p){NSData*d=[NSJSONSerialization dataWithJSONObject:VMJSONSafe(x) options:NSJSONWritingPrettyPrinted|NSJSONWritingSortedKeys error:NULL];Require(d&&[d writeToFile:p atomically:YES],@"Cannot write S37 source facts");}
int main(int argc,char**argv){@autoreleasepool{if(argc!=3)return 2;NSString*photo=@(argv[1]),*dir=@(argv[2]);@try{
