 NSData*plist=[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:@"styles.plist"]];NSDictionary*stored=[NSPropertyListSerialization propertyListWithData:plist options:0 format:NULL error:&error];NSDictionary*i=stored[@"i"];double gain=[i[@"Gain"]doubleValue],lo=[i[@"OriginalRangeMin"]doubleValue],hi=[i[@"OriginalRangeMax"]doubleValue];Require(gain>0&&isfinite(gain)&&isfinite(lo)&&isfinite(hi)&&hi>=lo,@"Missing measured Apple Log parameters");
