 id props=[NSClassFromString(@"_NUSemanticStyleProperties")semanticStylePropertiesFromData:plist fromVideo:NO keyTime:kCMTimeInvalid error:&error];Require(props!=nil,@"Native semantic metadata rejected");CIFilter*f=[NSClassFromString(@"PISemanticStyleFilter")new];[f setDefaults];CIImage*curve=[(id)f curveImageWithData:[props valueForKey:@"globalToneCurveData"]];Require(curve!=nil,@"Native GTC image missing");NSDictionary*gtc=Render(curve,Context(NULL),NULL,[dir stringByAppendingPathComponent:@"gtc_native.f32"]);
